import { colors, Theme, useTheme } from '@/theme'
import { Image } from 'expo-image'
import { X } from 'lucide-react-native'
import { ScrollView, TouchableOpacity, View } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { router } from 'expo-router'

const ASSET_DELETE_BUTTON_OFFSET = 10

type AssetsContainerProps = {
	chatAssets: string[]
	setChatAssets: (chatAssets: string[]) => void
}

export const AssetsContainer = ({
	chatAssets,
	setChatAssets
}: AssetsContainerProps) => {
	const { theme } = useTheme()

	const handleAssetViewPress = (asset: string) => {
		router.push({
			pathname: '/asset-view-modal',
			params: {
				asset
			}
		})
	}

	const handleRemoveImagePress = (index: number) => {
		setChatAssets(chatAssets.filter((_, i) => i !== index))
	}

	return (
		chatAssets.length > 0 && (
			<ScrollView
				horizontal
				showsHorizontalScrollIndicator={false}
				style={styles.chatAssetScrollViewContainer}
				contentContainerStyle={styles.chatAssetScrollViewContentContainer}
			>
				{chatAssets.map((asset, index) => (
					<View key={index}>
						<TouchableOpacity
							style={styles.chatAssetButton}
							onPress={() => handleAssetViewPress(asset)}
						>
							<Image
								source={{ uri: asset }}
								style={styles.chatAssetImageContainer}
								contentFit="cover"
							/>
						</TouchableOpacity>
						<TouchableOpacity
							style={styles.chatAssetDeleteButton(theme)}
							onPress={() => handleRemoveImagePress(index)}
						>
							<X size={16} color={colors[theme].gray[25]} />
						</TouchableOpacity>
					</View>
				))}
			</ScrollView>
		)
	)
}

const styles = defineStyles({
	chatAssetScrollViewContainer: {
		paddingHorizontal: 20,
		marginTop: -ASSET_DELETE_BUTTON_OFFSET,
		paddingTop: ASSET_DELETE_BUTTON_OFFSET
	},
	chatAssetScrollViewContentContainer: {
		gap: 12,
		paddingRight: 20
	},
	chatAssetButton: {
		borderRadius: 12,
		width: 80,
		height: 80,
		overflow: 'hidden'
	},
	chatAssetImageContainer: {
		width: '100%',
		height: '100%'
	},
	chatAssetDeleteButton: (theme: Theme) => ({
		overflow: 'hidden',
		position: 'absolute',
		top: -ASSET_DELETE_BUTTON_OFFSET,
		right: -ASSET_DELETE_BUTTON_OFFSET,
		backgroundColor: colors[theme].gray[900],
		borderRadius: 50,
		borderWidth: 2,
		borderColor: colors[theme].gray[25],
		padding: 2
	})
})
